const items = $input.all().map(i => i.json).filter(j => j && j.id);
if (!items.length) return [];
const f = j => j.fields || j;
const rdv = items.map(j => {
  const x = f(j);
  const acc = Array.isArray(x['Accompagnant']) ? x['Accompagnant'][0] : (x['Accompagnant'] || '');
  return { heure: x['Heure'] || '', type: x['Type'] || 'Rendez-vous', personne: x['Personne'] || '', acc: acc && acc.name ? acc.name : acc };
}).sort((a, b) => (a.heure || '99:99').localeCompare(b.heure || '99:99'));
const aCouvrir = rdv.filter(r => !r.acc).length;
const lignes = rdv.map(r => (r.heure || 'Journée') + ' · ' + r.type + (r.personne ? ' · ' + r.personne : '') + (r.acc ? ' (avec ' + r.acc + ')' : ' — à couvrir'));
const titre = (aCouvrir ? '⚠ ' : '') + "Aujourd'hui : " + rdv.length + (rdv.length > 1 ? ' rendez-vous' : ' rendez-vous') + (aCouvrir ? ', ' + aCouvrir + ' à couvrir' : '');
return [{ json: { titre, message: lignes.join('\n'), priority: aCouvrir ? 4 : 3 } }];
